"""DeepSeek-V4 sparse MLA decode (C4 layers, dsv4_fp8 padded-page pools) for MI355X (gfx950), in FlyDSL.

Per request b and head h: softmax with a per-head sink over two key lists, the sliding window's (swa_len[b] of its 128
slots) and the compressed list's (kv_len[b] of 1024); a slot < 0 is skipped. A key row is 448 e4m3 codes with seven
ue8m0 group scales (one a 64 dims) and 64 bf16 RoPE dims: K = V = its 512 dims. G = B H / 64 groups of 64 heads.

Producer workgroup (group, chunk of 64 keys, head block of HPW heads; 4 waves)
    The 1152 list entries are 18 chunks: 2 of the window, 16 of the compressed list. A chunk past its list's length is
    keyless: no work. Otherwise the 256 threads (4 a row) gather the chunk's 64 rows and assemble them to bf16 in LDS
    (the bits of the e4m3 code and its scale: no e4m3 subnormals or NaN, as in the format), then:
    - QK: S^T = K Q^T with bf16 MFMAs. Wave w is head tile ht = w % NHT of the block, part p = w / NHT of the tile's
      WPH waves. WPH = 1: the wave does all 16 k-steps; WPH > 1: k-steps p 16 / WPH .., the parts summed through LDS in
      pairs, one order, so every wave of the tile holds the same S.
    - softmax over the chunk's keys in every wave (max, exp2, sum), P = exp2(s - m) split hi + lo bf16.
    - PV: O^T = K^T P^T (V^T read with ds_read_tr16), wave p takes d tiles p 32 / WPH ..; f O / l is stored in f16 in
      the MFMA's layout (a wave's store 1 KB contiguous), f = 2^k bringing the chunk's |V| bound (from its rows' scale
      bytes and RoPE exponents, so |O / l| too) below 2^15; the record (m, l, 1 / f) a head.
Merge wave (group, head, half of the dims)
    Lane j < 18 takes chunk j's record (keyless chunks: zeros, by out-of-range buffer loads, no traffic); the wave
    reduces M and L = sum l_j 2^(m_j - M), adds the sink, sums the chunks' partials with weights l_j 2^(m_j - M) / (f_j Z)
    and writes out (bf16) and lse = M + log2 L (ln units; +inf for a request with no key).

G <= 8: one launch, with AKLR's kernel state. The producers, chunk-major (id = (c NHB2 + hb) G + group), then HPW / 4
merge workgroups a slot (group, head block). A slot's 2 HPW merge tasks go to the waves of its keyless chunks past its
last chunk with keys (lastc), then the appended ones, then lastc's own after its part (a wave takes two tasks when those
waves are fewer than the tasks). A merge wave waits only on the producers of the slot's chunks <= lastc.
  - No deadlock at any residency (CUs held by other work, a CU mask): a merge wave waits only on workgroups of lower id;
    each XCD dispatches its workgroups in id order, and producers never wait, so by induction on the id every
    workgroup is dispatched and finishes.
  - State (STATE_BYTES, zeroed once by AKLR): a slot's 18 chunk flags and its merge count. Every producer of the slot,
    keyless or not, reads its flag at its start and, once its partial is stored, writes it + 128: the slot's flags all
    hold 128 (calls of the slot so far) and are never more than one call stale, whichever shapes shared the state. A
    merge wave on a producer waits for its own flag + 128; an appended merge workgroup adds 512 / HPW to the merge
    count (128 a call, in step with the flags) and waits for its old value rounded down to 128, + 128. All of it is
    mod 2^32, a multiple of 128: a wrap is harmless (a stale flag is 128 short of the awaited value, never equal).
G > 8: two launches (producers, then one merge wave a task), no state.

Exactness: S and O accumulate in f32 from bf16 K, Q and hi + lo bf16 P (P to ~2^-16); the partials are f16 to relative
2^-11 of the chunk's |V| bound. Exact enough for any input in f32 / bf16 range (checked with group magnitudes
2^-10 .. 2^10): the rounding beyond the reference's is P's hi + lo split and the f16 partials (bf16 K is exact).

Scratch: one torch.empty a call (partials and records); nothing in it is read before this call writes it.
"""
import functools
import math
import struct
import types

import torch
import flydsl.compiler as flyc
from flydsl.compiler.kernel_function import CompilationContext
import flydsl.expr as fx
from flydsl._mlir import ir
from flydsl._mlir.dialects import arith as A, llvm as L, rocdl as R, vector as V, scf

D = 512
SWA = 128                     # window list entries a request
KVW = 1024                    # compressed list entries a request
CK = 64                       # keys a chunk
NCH = (SWA + KVW) // CK       # chunks a request
NSW = SWA // CK               # chunks of the window
PITCH = 1056                  # LDS bytes a K row (512 bf16 + pad)
LDS_MIN = 82 * 1024           # one part workgroup a CU while the grid fits the CUs
QK_DEPTH = 4                  # K reads ahead in QK
PV_DEPTH = 8                  # V^T reads ahead in PV
LOG2E = 1.4426950408889634
LN2 = 0.6931471805599453
OOB = 0x7FFFFFF0              # a buffer offset past the end: the load returns 0, no memory access
SC1 = 16                      # buffer cache policy sc1: the partials' stores write through (no dirty L2 lines at the end)
# heads a part workgroup by (groups, head groups of 64): small grids split the heads for parallelism
HPW_TABLE = types.MappingProxyType({(1, 1): 16, (2, 1): 16, (4, 1): 16, (8, 1): 16, (2, 2): 16, (4, 2): 16,
                                    (8, 2): 32})
# the kernel state, a slot (group < 8, head block < 4) each: its 18 chunks' flags (128 B apart), then its merge count
MC_OFF = 8 * 4 * 32 * 128
STATE_BYTES = MC_OFF + 8 * 4 * 128
PRELOAD_ARGS = 7              # the part kernel's first 7 pointer arguments preloaded into SGPRs


# ---------------------------------------------------------------- MLIR helpers

def raw(v):
    if isinstance(v, ir.Value):
        return v
    if hasattr(v, "ir_value"):
        return v.ir_value()
    return v


def ty_i(n):
    return ir.IntegerType.get_signless(n)


def i32t():
    return ty_i(32)


def i64t():
    return ty_i(64)


def f32t():
    return ir.F32Type.get()


def bf16t():
    return ir.BF16Type.get()


def vt(n, t):
    return ir.VectorType.get([n], t)


def ci(v, t=None):
    t = t or i32t()
    return A.ConstantOp(t, ir.IntegerAttr.get(t, v)).result


def cf(v):
    return A.ConstantOp(f32t(), ir.FloatAttr.get(f32t(), v)).result


def _v(x, t=None):
    if isinstance(x, int):
        return ci(x, t)
    if isinstance(x, float):
        return cf(x)
    return raw(x)


def add(a, b):
    a = _v(a)
    return A.addi(a, _v(b, a.type))


def sub(a, b):
    a = _v(a)
    return A.subi(a, _v(b, a.type))


def mul(a, b):
    a = _v(a)
    return A.muli(a, _v(b, a.type))


def udiv(a, b):
    a = _v(a)
    return A.divui(a, _v(b, a.type))


def urem(a, b):
    a = _v(a)
    return A.remui(a, _v(b, a.type))


def band(a, b):
    a = _v(a)
    return A.andi(a, _v(b, a.type))


def bor(a, b):
    a = _v(a)
    return A.ori(a, _v(b, a.type))


def bxor(a, b):
    a = _v(a)
    return A.xori(a, _v(b, a.type))


def shl(a, b):
    a = _v(a)
    return A.shli(a, _v(b, a.type))


def shr(a, b):
    a = _v(a)
    return A.shrui(a, _v(b, a.type))


def cmp(pred, a, b):
    a = _v(a)
    return A.cmpi(getattr(A.CmpIPredicate, pred), a, _v(b, a.type))


def fcmp(pred, a, b):
    return A.cmpf(getattr(A.CmpFPredicate, pred.upper()), _v(a), _v(b))


def sel(c, a, b):
    a = _v(a)
    return A.select(c, a, _v(b, a.type))


def fadd(a, b):
    return A.addf(_v(a), _v(b))


def fsub(a, b):
    return A.subf(_v(a), _v(b))


def fmul(a, b):
    return A.mulf(_v(a), _v(b))


def fmax(a, b):
    return A.maximumf(_v(a), _v(b))


def zext64(a):
    return A.extui(i64t(), _v(a))


def intr(res, name, args):
    return L.call_intrinsic(res, name, [_v(a) for a in args], [], [])


def exp2(x):
    return intr(f32t(), "llvm.amdgcn.exp2", [x])


def log2(x):
    return intr(f32t(), "llvm.amdgcn.log", [x])


def rcp(x):
    return intr(f32t(), "llvm.amdgcn.rcp", [x])


def perm(hi, lo, s):
    return intr(i32t(), "llvm.amdgcn.perm", [hi, lo, ci(s)])


def rfl(x):
    return R.readfirstlane(i32t(), _v(x))


def bperm(lane_src, x):
    """x (i32) from lane lane_src"""
    return R.ds_bpermute(i32t(), mul(lane_src, 4), _v(x))


def fbperm(lane_src, x):
    return A.bitcast(f32t(), bperm(lane_src, A.bitcast(i32t(), x)))


def dpp(x, ctrl, row_mask, ident):
    """x (f32) from the DPP-selected lane; lanes of masked-off rows get ident"""
    r = R.update_dpp(i32t(), ci(ident), A.bitcast(i32t(), x), ctrl, row_mask, 0xF, False)
    return A.bitcast(f32t(), r)


def wave_umax(x):
    """the largest of the 64 lanes' i32 x (unsigned), uniform"""
    for ctrl, rm in ((0xB1, 0xF), (0x4E, 0xF), (0x141, 0xF), (0x140, 0xF), (0x142, 0xA), (0x143, 0xC)):
        x = A.maxui(x, R.update_dpp(i32t(), ci(0), x, ctrl, rm, 0xF, False))
    return R.readlane(i32t(), x, ci(63))


def wave_reduce(x, op, ident):
    """op over the 64 lanes, the result uniform"""
    idb = int.from_bytes(struct.pack("<f", ident), "little", signed=True)
    for ctrl, rm in ((0xB1, 0xF), (0x4E, 0xF), (0x141, 0xF), (0x140, 0xF), (0x142, 0xA), (0x143, 0xC)):
        x = op(x, dpp(x, ctrl, rm, idb))
    return A.bitcast(f32t(), R.readlane(i32t(), A.bitcast(i32t(), x), ci(63)))


def gptr(v):
    """a 64-bit address (kernel argument) as a global pointer"""
    return L.inttoptr(ir.Type.parse("!llvm.ptr<1>"), raw(v))


# The three below emit no instruction: they are optimization barriers FlyDSL has no op for (each an empty inline asm
# that ties its operand to its result).

def opaque(v):
    """hide a uniform value (keeps select(p1, p2) from becoming two dependent kernel-argument loads)"""
    return L.inline_asm(v.type, [v], "; $0", "=s,0", has_side_effects=False)


def pin(v):
    """materialize a vector value here (its load is issued before, not sunk into a later branch)"""
    return L.inline_asm(v.type, [v], "; $0", "=v,0", has_side_effects=True)


def spin(v):
    """materialize a uniform value here (an SGPR read from the kernel arguments while earlier loads are out)"""
    return L.inline_asm(v.type, [v], "; $0", "=s,0", has_side_effects=True)


def psel(c, p1, p2):
    return A.select(c, opaque(p1), opaque(p2))


def gep(p, off):
    """p + off bytes (python int, i32 or i64 value)"""
    i8 = ty_i(8)
    if isinstance(off, int):
        return L.getelementptr(p.type, p, [], [off], i8, L.GEPNoWrapFlags.none)
    return L.getelementptr(p.type, p, [_v(off)], [-2147483648], i8, L.GEPNoWrapFlags.none)


def load(t, p, align=16):
    return L.load(t, p, alignment=align)


def store(v, p, align=16):
    L.store(_v(v), p, alignment=align)


def vext(v, i):
    return V.extract(v, [], [i])


def vfrom(t, xs):
    return V.from_elements(t, [_v(x) for x in xs])


def splat_f(n, x):
    t = vt(n, f32t())
    return A.ConstantOp(t, ir.DenseElementsAttr.get_splat(t, ir.FloatAttr.get(f32t(), x))).result


def mfma(a, b, c):
    return fx.rocdl.mfma_f32_16x16x32_bf16(vt(4, f32t()), [a, b, c])


def fence():
    fx.rocdl.sched_barrier(0)


def buf_rsrc(p, nbytes):
    return R.make_buffer_rsrc(ir.Type.parse("!llvm.ptr<8>"), p, ci(0, ty_i(16)), ci(nbytes, i64t()),
                              ci((7 << 12) | (4 << 15)))


def buf_store(v, rsrc, off, aux=0):
    R.raw_ptr_buffer_store(_v(v), rsrc, _v(off), ci(0), aux=ir.IntegerAttr.get(i32t(), aux))


def buf_load(t, rsrc, off, soff=0, aux=0):
    return R.raw_ptr_buffer_load(t, rsrc, _v(off), _v(soff), aux=ir.IntegerAttr.get(i32t(), aux))


def atomic_add(p, v):
    return L.atomicrmw(L.AtomicBinOp.add, p, _v(v), L.AtomicOrdering.monotonic, syncscope="agent", alignment=4)


def atomic_store(p, v):
    L.store(_v(v), p, alignment=4, ordering=L.AtomicOrdering.monotonic, syncscope="agent")


def lds_ptr():
    return fx.to_llvm_ptr(fx.get_dyn_shared())


def atomic_load(p):
    return L.load(i32t(), p, alignment=4, ordering=L.AtomicOrdering.monotonic, syncscope="agent")


class If:
    """with If(cond).then(): ...   (no results)"""

    def __init__(self, cond):
        self.op = scf.IfOp(_v(cond), [], has_else=False)

    def then(self):
        return _Blk(self.op.then_block)


class _Blk:
    def __init__(self, blk):
        self.blk = blk

    def __enter__(self):
        self.ip = ir.InsertionPoint(self.blk)
        self.ip.__enter__()

    def __exit__(self, *a):
        scf.YieldOp([])
        self.ip.__exit__(*a)


# ---------------------------------------------------------------- layout of the scratch

def part_bytes(G):
    return G * NCH * 64 * D * 2         # f16 partials [group][chunk][head tile][block of 2 d tiles][head][g][8]


def scratch_bytes(G):
    return part_bytes(G) + G * 64 * NCH * 16     # + (m, l, 1 / f, 0) [group][head][chunk]


def assemble16(x, s16):
    """4 dwords of e4m3 codes and the group's (c - 7) << 7 in both halves -> 8 dwords of bf16 pairs: per half
    [b & 0x7f, the sign of b at bit 3]; << 4 puts the sign at bit 15, exponent and mantissa at 4 .. 10"""
    out = []
    for k in range(4):
        xk = vext(x, k)
        am = band(xk, 0x7F7F7F7F)
        sm = band(shr(xk, 4), 0x08080808)
        for sel_ in (0x05010400, 0x07030602):
            out.append(add(shl(perm(sm, am, sel_), 4), s16))
    return out


# ---------------------------------------------------------------- the part kernel

def part_body(pSWL, pKVL, pSWI, pKVI, pWS, pQ, pSWP, pKVP, scale2, G, NHB, HPW, SROWS, SPB, KROWS, KPB, early=None,
              fin=None):
    NHB2 = 64 // HPW                  # head blocks a group
    NHT = HPW // 16                   # head tiles a block
    WPH = 4 // NHT                    # waves a head tile
    KSW = 16 // WPH                   # QK k-steps a wave
    NNT = 32 // WPH                   # PV d tiles a wave
    KB = CK * PITCH
    tid = raw(fx.thread_idx.x)
    L_ = raw(fx.block_idx.x)
    grp = urem(L_, G) if G > 1 else ci(0)
    rest = udiv(L_, G) if G > 1 else L_
    hb = urem(rest, NHB2) if NHB2 > 1 else ci(0)
    c = udiv(rest, NHB2) if NHB2 > 1 else rest
    lane = band(tid, 63)
    w = rfl(shr(tid, 6))
    ht = band(w, NHT - 1) if NHT > 1 else ci(0)
    part = shr(w, NHT.bit_length() - 1) if WPH > 1 else ci(0)
    lds = lds_ptr()
    wsr = buf_rsrc(gptr(pWS), scratch_bytes(G))
    b = udiv(grp, NHB) if NHB > 1 else grp
    is_swa = cmp("ult", c, NSW)
    start = sel(is_swa, mul(c, CK), mul(sub(c, NSW), CK))
    # the index entries and the lengths go out first (their pointers preloaded), then the rest of the arguments
    e = add(start, lane)
    ioff = sel(is_swa, add(mul(b, SWA), e), add(mul(b, KVW), e))
    idx = load(i32t(), gep(psel(is_swa, gptr(pSWI), gptr(pKVI)), mul(ioff, 4)), 4)
    lsw = load(i32t(), gep(gptr(pSWL), mul(b, 4)), 4)
    lkv = load(i32t(), gep(gptr(pKVL), mul(b, 4)), 4)
    extra = early(grp, hb, c) if early is not None else None
    fence()
    qp, swap, kvp = (gptr(spin(x)) for x in (raw(pQ), raw(pSWP), raw(pKVP)))
    scale2 = spin(scale2)
    idx = pin(idx)
    lsw, lkv = pin(lsw), pin(lkv)
    if extra is not None:
        extra = pin(extra)
    ln = sel(is_swa, lsw, lkv)
    g = shr(lane, 4)
    l16 = band(lane, 15)
    head = add(add(mul(hb, HPW), mul(ht, 16)), l16)          # this lane's head in the group (QK / PV)
    qrow = mul(add(mul(grp, 64), head), D * 2)

    with If(cmp("slt", start, ln)).then():
        valid = A.andi(cmp("slt", e, ln), cmp("sge", idx, 0))
        vmask = R.ballot(i64t(), valid)

        # ---- the rows: thread (r = tid / 4, q = tid % 4): fp8 pieces q + 4 i (i < 7), rope pieces q, q + 4
        r = shr(tid, 2)
        q = band(tid, 3)
        rvalid = cmp("ne", bperm(r, A.extui(i32t(), valid)), 0)
        slot = sel(rvalid, bperm(r, idx), 0)
        page = shr(slot, sel(is_swa, SROWS.bit_length() - 1, KROWS.bit_length() - 1))
        row = band(slot, sel(is_swa, SROWS - 1, KROWS - 1))
        pg64 = mul(zext64(page), zext64(sel(is_swa, SPB, KPB)))
        doff = add(pg64, zext64(mul(row, 576)))
        soff = add(pg64, zext64(add(sel(is_swa, SROWS * 576, KROWS * 576), mul(row, 8))))
        poolp = psel(is_swa, swap, kvp)
        rowp = gep(poolp, doff)
        fp8 = [load(vt(4, i32t()), gep(rowp, add(mul(q, 16), 64 * i))) for i in range(7)]
        rope = [load(vt(4, i32t()), gep(rowp, add(448, add(mul(q, 16), 64 * i)))) for i in range(2)]
        sc = load(vt(2, i32t()), gep(poolp, soff), 8)
        # Q after the rows (the waits are in order: the rows' do not wait for Q), only this wave's k-steps
        fence()
        qv = [load(vt(8, bf16t()), gep(qp, add(qrow, add(add(mul(g, 16), mul(part, 64 * KSW)), 64 * j))))
              for j in range(KSW)]
        fence()
        sc0 = sel(rvalid, vext(sc, 0), 0x7F7F7F7F)
        sc1 = sel(rvalid, vext(sc, 1), 0x7F7F7F7F)

        # ---- assemble to bf16: row r at r PITCH, fp8 piece j (16 codes) -> 32 B at 32 j, rope piece j -> 896 + 16 j
        lrow = mul(r, PITCH)
        for i, x in enumerate(fp8):
            cb = band(shr(sc0 if i < 4 else sc1, 8 * (i % 4)), 255)
            o = assemble16(x, mul(shl(sub(cb, 7), 7), 0x00010001))
            lo = add(lrow, mul(add(q, 4 * i), 32))
            store(vfrom(vt(4, i32t()), o[0:4]), gep(lds, lo))
            store(vfrom(vt(4, i32t()), o[4:8]), gep(lds, add(lo, 16)))
        for i, x in enumerate(rope):
            store(x, gep(lds, add(lrow, add(896, mul(add(q, 4 * i), 16)))))
        # a bound on the chunk's |V|: an e4m3 value of group scale byte c is < 2^(c - 118), a bf16 one of exponent
        # field e < 2^(e - 126); the rows' largest c + 8 and e, over the workgroup (through LDS, at the barrier below)
        bnd = ci(0)
        for k in range(7):
            bnd = A.maxui(bnd, band(shr(sc0 if k < 4 else sc1, 8 * (k % 4)), 255))
        bnd = add(bnd, 8)
        for x in rope:
            for k in range(4):
                xk = vext(x, k)
                bnd = A.maxui(bnd, A.maxui(band(shr(xk, 7), 255), band(shr(xk, 23), 255)))
        bnd = wave_umax(bnd)
        with If(cmp("eq", lane, 0)).then():
            store(bnd, gep(lds, add(KB + 8192, mul(w, 4))), 4)
        fx.gpu.barrier()
        ex = load(i32t(), gep(lds, KB + 8192), 4)
        for k in range(1, 4):
            ex = A.maxui(ex, load(i32t(), gep(lds, KB + 8192 + 4 * k), 4))
        ex = A.minui(A.maxui(rfl(ex), ci(15)), ci(254))     # |O / l| <= max |V| < 2^(ex - 126)

        # ---- S^T tiles tt (keys 16 tt + 4 g + i, head `head`) over this wave's k-steps
        acc = [splat_f(4, 0.0) for _ in range(4)]
        kbase = add(add(mul(l16, PITCH), mul(g, 16)), mul(part, 64 * KSW))

        def qk_reads(j):
            return [load(vt(8, bf16t()), gep(lds, add(kbase, 16 * tt * PITCH + 64 * j))) for tt in range(4)]
        depth = min(QK_DEPTH, KSW)
        pend = [qk_reads(j) for j in range(depth)]
        for j in range(KSW):
            if j + depth < KSW:
                pend.append(qk_reads(j + depth))
            fence()
            cur = pend.pop(0)
            for tt in range(4):
                acc[tt] = mfma(cur[tt], qv[j], acc[tt])
            fence()

        if WPH > 1:
            # parts p >= WPH / 2 hand theirs to p - WPH / 2, which adds its own and puts the pair's sum back; every
            # wave then adds the pair sums (one order: the same S in every wave of the tile)
            H2 = WPH // 2
            sxb = lambda sl, tt: add(KB, add(mul(add(mul(add(mul(ht, H2), sl), 4), tt), 1024), mul(lane, 16)))
            hi_ = cmp("uge", part, H2)
            slot_ = sel(hi_, sub(part, H2), part) if H2 > 1 else ci(0)
            with If(hi_).then():
                for tt in range(4):
                    store(acc[tt], gep(lds, sxb(slot_, tt)))
            fx.gpu.barrier()
            with If(A.xori(hi_, ci(1, ty_i(1)))).then():
                for tt in range(4):
                    store(A.addf(acc[tt], load(vt(4, f32t()), gep(lds, sxb(slot_, tt)))), gep(lds, sxb(slot_, tt)))
            fx.gpu.barrier()
            acc = [load(vt(4, f32t()), gep(lds, sxb(ci(0), tt))) for tt in range(4)]
            for sl in range(1, H2):
                acc = [A.addf(acc[tt], load(vt(4, f32t()), gep(lds, sxb(ci(sl), tt)))) for tt in range(4)]

        # ---- softmax over the chunk's 64 keys (masked: past the length, or a slot < 0)
        ninf = cf(-math.inf)
        s = []
        mloc = ninf
        for tt in range(4):
            for i in range(4):
                key = add(16 * tt + i, mul(g, 4))
                okk = cmp("ne", band(A.shrui(vmask, zext64(key)), ci(1, i64t())), ci(0, i64t()))
                x = sel(okk, fmul(vext(acc[tt], i), scale2), ninf)
                s.append(x)
                mloc = fmax(mloc, x)
        mloc = fmax(mloc, fbperm(bxor(lane, 16), mloc))
        mloc = fmax(mloc, fbperm(bxor(lane, 32), mloc))
        msafe = sel(fcmp("oeq", mloc, ninf), cf(0.0), mloc)
        p = [exp2(fsub(x, msafe)) for x in s]
        lsum = p[0]
        for x in p[1:]:
            lsum = fadd(lsum, x)
        lsum = fadd(lsum, fbperm(bxor(lane, 16), lsum))
        lsum = fadd(lsum, fbperm(bxor(lane, 32), lsum))
        # P^T (hi + lo bf16) of key tile tt: positions (tt % 2) 4 + i of PV k-step tt / 2
        pv4 = []
        for tt in range(4):
            v4 = vfrom(vt(4, f32t()), p[4 * tt: 4 * tt + 4])
            hi = A.truncf(vt(4, bf16t()), v4)
            pv4.append((hi, A.truncf(vt(4, bf16t()), A.subf(v4, A.extf(vt(4, f32t()), hi)))))
        phis = [V.shuffle(pv4[2 * st][0], pv4[2 * st + 1][0], list(range(8))) for st in range(2)]
        plos = [V.shuffle(pv4[2 * st][1], pv4[2 * st + 1][1], list(range(8))) for st in range(2)]
        rec = add(part_bytes(G), mul(add(mul(add(mul(grp, 64), head), NCH), c), 16))
        with If(A.andi(cmp("ult", lane, 16), cmp("eq", part, 0))).then():
            buf_store(vfrom(vt(4, f32t()), [msafe, lsum, A.bitcast(f32t(), shl(sub(ex, 14), 23)), cf(0.0)]), wsr, rec,
                      SC1)

        # ---- O^T = K^T P^T on d tiles NNT part + n: lane d = 16 n + 4 g + i, head `head`
        o = [splat_f(4, 0.0) for _ in range(NNT)]
        trbase = add(add(mul(add(mul(g, 4), shr(l16, 2)), PITCH), mul(band(l16, 3), 8)), mul(part, 32 * NNT))

        def pv_reads(st, n):
            off = 32 * st * PITCH + 32 * n
            a1 = R.ds_read_tr16_b64(vt(4, bf16t()), gep(lds, add(trbase, off)))
            a2 = R.ds_read_tr16_b64(vt(4, bf16t()), gep(lds, add(trbase, off + 16 * PITCH)))
            return (a1, a2)
        steps = [(st, n) for st in range(2) for n in range(NNT)]
        pend = [pv_reads(*steps[i]) for i in range(PV_DEPTH)]
        for i, (st, n) in enumerate(steps):
            if i + PV_DEPTH < len(steps):
                pend.append(pv_reads(*steps[i + PV_DEPTH]))
            fence()
            a1, a2 = pend.pop(0)
            av = V.shuffle(a1, a2, list(range(8)))
            o[n] = mfma(av, phis[st], o[n])
            o[n] = mfma(av, plos[st], o[n])
            fence()

        # ---- the partial f O / l in f16, f = 2^(141 - ex) (the chunk's |V| bound to < 2^15: f16's range; the merge
        # multiplies by 1 / f): [group][chunk][head tile][block of 2 d tiles][head][g][8 f16], from the registers (each
        # store a wave's 1 KB, contiguous)
        fl = sel(fcmp("ogt", lsum, cf(0.0)), fmul(rcp(lsum), A.bitcast(f32t(), shl(sub(268, ex), 23))), cf(0.0))
        fv = V.broadcast(vt(4, f32t()), fl)
        pb0 = add(mul(add(mul(add(mul(grp, NCH), c), 4), add(mul(hb, NHT), ht)), 16384), add(mul(l16, 64), mul(g, 16)))
        for k in range(NNT // 2):
            v8 = V.shuffle(A.mulf(o[2 * k], fv), A.mulf(o[2 * k + 1], fv), list(range(8)))
            buf_store(A.truncf(vt(8, ir.F16Type.get()), v8), wsr, add(pb0, mul(add(mul(part, NNT // 2), k), 1024)), SC1)

    if fin is not None:
        fin(tid, grp, hb, c, rfl(lsw), rfl(lkv), extra)


def fused_wgs(G, HPW):
    """the fused grid: the producers, then the merge workgroups (4 waves, a (head, half) each)"""
    return G * NCH * (64 // HPW) + G * (64 // HPW) * (HPW // 4)


def part_lds(G, HPW, nwg=None):
    nwg = nwg or G * NCH * (64 // HPW)
    need = CK * PITCH + 8 * 1024 + 64
    return max(need, LDS_MIN) if nwg <= 256 else need


@flyc.kernel
def part_kernel(pSWL: fx.Int64, pKVL: fx.Int64, pSWI: fx.Int64, pKVI: fx.Int64, pWS: fx.Int64, pQ: fx.Int64,
                pSWP: fx.Int64, pKVP: fx.Int64, scale2: fx.Float32, G: fx.Constexpr[int], NHB: fx.Constexpr[int],
                HPW: fx.Constexpr[int], SROWS: fx.Constexpr[int], SPB: fx.Constexpr[int], KROWS: fx.Constexpr[int],
                KPB: fx.Constexpr[int]):
    part_body(pSWL, pKVL, pSWI, pKVI, pWS, pQ, pSWP, pKVP, raw(scale2), G, NHB, HPW, SROWS, SPB, KROWS, KPB)


# ---------------------------------------------------------------- the merge kernel

def merge_body(pSWL, pKVL, pWS, pSINK, pOUT, pLSE, kv_scale, G, NHB, SINK):
    tid = raw(fx.thread_idx.x)
    t = add(mul(raw(fx.block_idx.x), 4), rfl(shr(tid, 6)))        # (group, head, half)
    merge_wave(pSWL, pKVL, pWS, pSINK, pOUT, pLSE, kv_scale, G, NHB, SINK, shr(t, 7),
               [(band(shr(t, 1), 63), [band(t, 1)])])


def merge_wave(pSWL, pKVL, pWS, pSINK, pOUT, pLSE, kv_scale, G, NHB, SINK, grp, heads, wait=None):
    """one wave: of group grp, each (head mh, halves hfs of the dims) in heads; wait() returns once every chunk's
    partial is in. Lane j < 18 takes chunk j's record; lane l the dims 32 (8 hf + l / 8) + 16 (l % 2) + 4 ((l / 2) % 4)
    + (0 .. 3) of each half."""
    tid = raw(fx.thread_idx.x)
    lane = band(tid, 63)
    b = udiv(grp, NHB) if NHB > 1 else grp
    wsr = buf_rsrc(gptr(pWS), scratch_bytes(G))
    lsw = load(i32t(), gep(gptr(pSWL), mul(b, 4)), 4)
    lkv = load(i32t(), gep(gptr(pKVL), mul(b, 4)), 4)
    sinks = []
    for mh, _ in heads:
        hglob = add(mul(urem(grp, NHB), 64), mh) if NHB > 1 else mh
        sinks.append(load(f32t(), gep(gptr(pSINK), mul(hglob, 4)), 4) if SINK else cf(-math.inf))
    nsw_act = A.minui(shr(add(A.maxsi(lsw, ci(0)), CK - 1), 6), ci(NSW))
    nkv_act = A.minui(shr(add(A.maxsi(lkv, ci(0)), CK - 1), 6), ci(NCH - NSW))

    def chunk_active(cc):
        return cmp("ult", ci(cc), nsw_act) if cc < NSW else cmp("ult", ci(cc - NSW), nkv_act)
    lact = sel(cmp("ult", lane, NSW), cmp("ult", lane, nsw_act), cmp("ult", sub(lane, NSW), nkv_act))
    lact = A.andi(lact, cmp("ult", lane, NCH))
    sos = [rfl(sel(chunk_active(cc), cc * 65536, OOB)) for cc in range(NCH)]
    pol = 0
    if wait is not None:
        wait()
        pol = SC1                     # (written by other CUs in this launch: past this XCD's L2)
    loads = []
    for mh, hfs in heads:
        mo = sel(lact, add(part_bytes(G), mul(add(mul(add(mul(grp, 64), mh), NCH), lane), 16)), OOB)
        ml = buf_load(vt(4, f32t()), wsr, mo, aux=pol)
        ocs = []
        for hf in hfs:
            oo = add(add(add(mul(mul(grp, NCH), 65536), mul(shr(mh, 4), 16384)), mul(add(mul(hf, 8), shr(lane, 3)), 1024)),
                     add(add(mul(band(mh, 15), 64), mul(band(shr(lane, 1), 3), 16)), mul(band(lane, 1), 8)))
            ocs.append([buf_load(vt(4, ir.F16Type.get()), wsr, oo, sos[cc], aux=pol) for cc in range(NCH)])
        loads.append((ml, ocs))
    ninf = cf(-math.inf)
    for (mh, hfs), sink, (ml, ocs) in zip(heads, sinks, loads):
        mc, lc = vext(ml, 0), vext(ml, 1)
        alive = fcmp("ogt", lc, cf(0.0))
        M = wave_reduce(sel(alive, mc, ninf), fmax, -math.inf)
        Ms = sel(fcmp("oeq", M, ninf), cf(0.0), M)
        x = sel(alive, fmul(lc, exp2(fsub(mc, Ms))), cf(0.0))
        Lsum = wave_reduce(x, fadd, 0.0)
        Z = fadd(Lsum, exp2(fsub(fmul(sink, LOG2E), Ms)))
        empty = fcmp("oeq", Lsum, cf(0.0))
        f = sel(empty, cf(0.0), fmul(rcp(Z), kv_scale))
        orow = add(mul(grp, 64), mh)
        xs = fmul(fmul(x, vext(ml, 2)), f)              # chunk weight / its f
        wcs = [A.bitcast(f32t(), R.readlane(i32t(), A.bitcast(i32t(), xs), ci(cc))) for cc in range(NCH)]
        for hf, oc in zip(hfs, ocs):
            accv = splat_f(4, 0.0)
            for cc in range(NCH):            # (an inactive chunk: zeros, weight 0)
                accv = fx.math.fma(A.extf(vt(4, f32t()), oc[cc]), V.broadcast(vt(4, f32t()), wcs[cc]), accv)
            d = add(add(mul(add(mul(hf, 8), shr(lane, 3)), 32), mul(band(lane, 1), 16)), mul(band(shr(lane, 1), 3), 4))
            store(A.truncf(vt(4, bf16t()), accv), gep(gptr(pOUT), mul(add(mul(orow, D), d), 2)), 8)
        lse = sel(empty, cf(math.inf), fmul(fadd(Ms, log2(Lsum)), LN2))
        with If(A.andi(cmp("eq", lane, 0), cmp("eq", hfs[0], 0))).then():
            store(lse, gep(gptr(pLSE), mul(orow, 4)), 4)


@flyc.kernel
def merge_kernel(pSWL: fx.Int64, pKVL: fx.Int64, pWS: fx.Int64, pSINK: fx.Int64, pOUT: fx.Int64, pLSE: fx.Int64,
                 kv_scale: fx.Float32, G: fx.Constexpr[int], NHB: fx.Constexpr[int], SINK: fx.Constexpr[int]):
    merge_body(pSWL, pKVL, pWS, pSINK, pOUT, pLSE, raw(kv_scale), G, NHB, SINK)


def fused_body(pSWL, pKVL, pSWI, pKVI, pWS, pST, pQ, pSWP, pKVP, pSINK, pOUT, pLSE, scale2, kv_scale, G, NHB, HPW,
               SROWS, SPB, KROWS, KPB, SINK):
    """Workgroups L < NPROD: the part kernel's, chunk-major (L = (c NHB2 + hb) G + grp); then NAPP = HPW / 4 merge
    workgroups a slot (group, head block). A slot's merge waves, in order: those of its chunks past its last chunk with
    keys (lastc), the appended ones, then lastc's own (after its part): AV of them, >= HPW. Its 2 HPW merge tasks
    (head, half): wave k does task k and, if AV < 2 HPW, task k + AV. A merge wave waits only on the producers of
    chunks <= lastc, all of lower ids."""
    NHB2 = 64 // HPW
    NPROD = G * NCH * NHB2
    NTASK = 2 * HPW
    NAPP = HPW // 4
    L_ = raw(fx.block_idx.x)
    tid = raw(fx.thread_idx.x)
    lane = band(tid, 63)
    w = rfl(shr(tid, 6))
    st = gptr(pST)
    flag = lambda grp, hb, c: gep(st, add(mul(add(mul(grp, 4), hb), 32 * 128), mul(c, 128)))
    mcount = lambda grp, hb: gep(st, add(MC_OFF, mul(add(mul(grp, 4), hb), 128)))

    def last_active(nsw, nkv):
        """the slot's chunks with keys (has), and the last of them (0 if none)"""
        nswc = A.minui(shr(add(A.maxsi(nsw, ci(0)), CK - 1), 6), ci(NSW))
        nkvc = A.minui(shr(add(A.maxsi(nkv, ci(0)), CK - 1), 6), ci(NCH - NSW))
        lastc = sel(cmp("ugt", nkvc, 0), add(nkvc, NSW - 1), A.maxsi(sub(nswc, 1), ci(0)))
        has = lambda c: sel(cmp("ult", c, NSW), cmp("ult", c, nswc), cmp("ult", sub(c, NSW), nkvc))
        return lastc, has

    def merge(grp, hb, k, lastc, has, target):
        """wave k of the slot's merge waves; target(): this call's flag value"""
        av = add(mul(sub(NCH - 1, lastc), 4), 4 * NAPP + 4)
        t2 = add(k, av)
        own1 = cmp("ult", k, NTASK)
        own2 = cmp("ult", t2, NTASK)

        def wait():
            # lane j < 18: chunk j's flag, if j has keys (its partial is read), until each is this call's value
            tv = target()
            mine = A.andi(cmp("ult", lane, NCH), has(lane))
            fl = flag(grp, hb, A.minui(lane, ci(NCH - 1)))
            wl = scf.WhileOp([i32t()], [ci(0)])
            before = wl.before.blocks.append(i32t())
            with ir.InsertionPoint(before):
                ok = A.ori(cmp("eq", atomic_load(fl), tv), A.xori(mine, ci(1, ty_i(1))))
                scf.ConditionOp(cmp("ne", R.ballot(i64t(), ok), ci(-1, i64t())), [ci(0)])
            after = wl.after.blocks.append(i32t())
            with ir.InsertionPoint(after):
                R.s_sleep(1)
                scf.YieldOp([after.arguments[0]])
        task = lambda t: (add(mul(hb, HPW), shr(t, 1)), [band(t, 1)])
        with If(A.andi(own1, A.xori(own2, ci(1, ty_i(1))))).then():
            merge_wave(pSWL, pKVL, pWS, pSINK, pOUT, pLSE, kv_scale, G, NHB, SINK, grp, [task(k)], wait=wait)
        with If(own2).then():
            merge_wave(pSWL, pKVL, pWS, pSINK, pOUT, pLSE, kv_scale, G, NHB, SINK, grp, [task(k), task(t2)], wait=wait)

    with If(cmp("ult", L_, NPROD)).then():
        def early(grp, hb, c):
            # this producer's flag: 128 (calls of the slot so far), for every chunk of the slot alike
            return load(i32t(), flag(grp, hb, c), 4)

        def fin(tid_, grp, hb, c, nsw, nkv, flag0v):
            flag0 = rfl(flag0v)
            lastc, has = last_active(nsw, nkv)
            # every wave's partial stores done, then this call's flag value (keyless chunks too: no flag is ever
            # more than a call behind)
            R.s_waitcnt(0)
            fx.gpu.barrier()
            target = lambda: add(flag0, 128)
            with If(cmp("eq", tid_, 0)).then():
                atomic_store(flag(grp, hb, c), target())
            with If(cmp("ugt", c, lastc)).then():
                merge(grp, hb, add(mul(sub(sub(c, lastc), 1), 4), w), lastc, has, target)
            with If(cmp("eq", c, lastc)).then():
                merge(grp, hb, add(mul(sub(NCH - 1, lastc), 4), add(4 * NAPP, w)), lastc, has, target)
        part_body(pSWL, pKVL, pSWI, pKVI, pWS, pQ, pSWP, pKVP, scale2, G, NHB, HPW, SROWS, SPB, KROWS, KPB, early=early,
                  fin=fin)
    with If(cmp("uge", L_, NPROD)).then():
        m = sub(L_, NPROD)
        slot = udiv(m, NAPP)
        grp = udiv(slot, NHB2) if NHB2 > 1 else slot
        hb = urem(slot, NHB2) if NHB2 > 1 else ci(0)
        b = udiv(grp, NHB) if NHB > 1 else grp
        nsw = rfl(load(i32t(), gep(gptr(pSWL), mul(b, 4)), 4))
        nkv = rfl(load(i32t(), gep(gptr(pKVL), mul(b, 4)), 4))
        # the call: the slot's merge count (128 a call: 512 / HPW each of its NAPP workgroups) before this
        # workgroup's arrival, rounded down to 128, is the flags' value before this call
        xb = lds_ptr()
        with If(cmp("eq", tid, 0)).then():
            store(atomic_add(mcount(grp, hb), 512 // HPW), xb, 4)
        fx.gpu.barrier()
        mold = rfl(load(i32t(), xb, 4))
        lastc, has = last_active(nsw, nkv)
        k = add(add(mul(sub(NCH - 1, lastc), 4), mul(urem(m, NAPP), 4)), w)
        merge(grp, hb, k, lastc, has, lambda: add(band(mold, -128), 128))


@flyc.kernel
def fused_kernel(pSWL: fx.Int64, pKVL: fx.Int64, pSWI: fx.Int64, pKVI: fx.Int64, pWS: fx.Int64, pST: fx.Int64,
                 pQ: fx.Int64, pSWP: fx.Int64, pKVP: fx.Int64, pSINK: fx.Int64, pOUT: fx.Int64, pLSE: fx.Int64,
                 scale2: fx.Float32, kv_scale: fx.Float32, G: fx.Constexpr[int], NHB: fx.Constexpr[int],
                 HPW: fx.Constexpr[int], SROWS: fx.Constexpr[int], SPB: fx.Constexpr[int], KROWS: fx.Constexpr[int],
                 KPB: fx.Constexpr[int], SINK: fx.Constexpr[int]):
    fused_body(pSWL, pKVL, pSWI, pKVI, pWS, pST, pQ, pSWP, pKVP, pSINK, pOUT, pLSE, raw(scale2), raw(kv_scale), G, NHB,
               HPW, SROWS, SPB, KROWS, KPB, SINK)


@flyc.jit
def launch_fused(pSWL: fx.Int64, pKVL: fx.Int64, pSWI: fx.Int64, pKVI: fx.Int64, pWS: fx.Int64, pST: fx.Int64,
                 pQ: fx.Int64, pSWP: fx.Int64, pKVP: fx.Int64, pSINK: fx.Int64, pOUT: fx.Int64, pLSE: fx.Int64,
                 scale2: fx.Float32, kv_scale: fx.Float32, G: fx.Constexpr[int], NHB: fx.Constexpr[int],
                 HPW: fx.Constexpr[int], SROWS: fx.Constexpr[int], SPB: fx.Constexpr[int], KROWS: fx.Constexpr[int],
                 KPB: fx.Constexpr[int], SINK: fx.Constexpr[int], stream: fx.Stream = fx.Stream(None)):
    fused_kernel(pSWL, pKVL, pSWI, pKVI, pWS, pST, pQ, pSWP, pKVP, pSINK, pOUT, pLSE, scale2, kv_scale, G, NHB, HPW,
                 SROWS, SPB, KROWS, KPB, SINK).launch(
        grid=(fused_wgs(G, HPW), 1, 1), block=(256, 1, 1), smem=part_lds(G, HPW, fused_wgs(G, HPW)), stream=stream)


@flyc.jit
def launch_part(pSWL: fx.Int64, pKVL: fx.Int64, pSWI: fx.Int64, pKVI: fx.Int64, pWS: fx.Int64, pQ: fx.Int64,
                pSWP: fx.Int64, pKVP: fx.Int64, scale2: fx.Float32, G: fx.Constexpr[int], NHB: fx.Constexpr[int],
                HPW: fx.Constexpr[int], SROWS: fx.Constexpr[int], SPB: fx.Constexpr[int], KROWS: fx.Constexpr[int],
                KPB: fx.Constexpr[int], stream: fx.Stream = fx.Stream(None)):
    part_kernel(pSWL, pKVL, pSWI, pKVI, pWS, pQ, pSWP, pKVP, scale2, G, NHB, HPW, SROWS, SPB, KROWS, KPB).launch(
        grid=(G * NCH * (64 // HPW), 1, 1), block=(256, 1, 1), smem=part_lds(G, HPW), stream=stream)


@flyc.jit
def launch_merge(pSWL: fx.Int64, pKVL: fx.Int64, pWS: fx.Int64, pSINK: fx.Int64, pOUT: fx.Int64, pLSE: fx.Int64,
                 kv_scale: fx.Float32, G: fx.Constexpr[int], NHB: fx.Constexpr[int], SINK: fx.Constexpr[int],
                 stream: fx.Stream = fx.Stream(None)):
