        grid=(G * 32, 1, 1), block=(256, 1, 1), stream=stream)


# ---------------------------------------------------------------- the entry

@functools.cache
def _config(B, H, srows, spb, krows, kpb, sm_scale, kv_scale):
    """(compiled launchers, their constants) for one shape: G groups of 64 heads, the heads a part workgroup"""
    nhb = H // 64
    G = B * nhb
    hpw = HPW_TABLE.get((G, nhb), 64)
    fused = G <= 8
    nwg = fused_wgs(G, hpw) if fused else G * NCH * (64 // hpw)
    part_hints = {"waves_per_eu": 1 if nwg <= 256 else 2,
                  "llvm_options": {"amdgpu-kernarg-preload": True, "amdgpu-kernarg-preload-count": PRELOAD_ARGS}}
    consts = dict(fused=fused, G=G, NHB=nhb, HPW=hpw, SROWS=srows, SPB=spb, KROWS=krows, KPB=kpb,
                  scale2=float(sm_scale * kv_scale * LOG2E), kv_scale=float(kv_scale), ws=scratch_bytes(G))
    return types.MappingProxyType(dict(consts, part_hints=types.MappingProxyType(part_hints)))


def run(*, q, kv_cache, sparse_indices, sparse_lens, extra_kv_cache, extra_sparse_indices, extra_sparse_lens,
        block_table=None, cache_seqlens=None, cu_seqlens_k=None, causal=False, head_dim_v=D, sm_scale, sinks,
        kv_cache_format="dsv4_fp8", kv_scale=1.0, return_lse=True, kv_cache_layout="padded_pages", output, lse,
        state=None):
    """The AKLR entry: out[b][0][h] (bf16) and lse[b][0][h] (f32, ln) of the sparse decode, see the module docstring.
    kv_cache / extra_kv_cache: the window's / compressed pools, [pages][page_rows][1][584] e4m3 views of padded pages."""
    B, _, H, _ = q.shape
    assert kv_cache_format == "dsv4_fp8" and kv_cache_layout == "padded_pages" and head_dim_v == D and not causal
    assert block_table is None and cache_seqlens is None and cu_seqlens_k is None
    assert H % 64 == 0 and q.shape == (B, 1, H, D) and q.dtype == torch.bfloat16 and q.is_contiguous()
    assert output.shape == q.shape and output.dtype == torch.bfloat16 and output.is_contiguous()
    for idx, ln, w in ((sparse_indices, sparse_lens, SWA), (extra_sparse_indices, extra_sparse_lens, KVW)):
        assert idx.shape == (B, 1, w) and idx.dtype == torch.int32 and idx.is_contiguous()
        assert ln.shape == (B,) and ln.dtype == torch.int32 and ln.is_contiguous()
    for pool in (kv_cache, extra_kv_cache):
        assert pool.dtype == torch.float8_e4m3fn and pool.shape[2:] == (1, 584) and pool.stride()[1:] == (584, 584, 1)
        assert pool.shape[1] & (pool.shape[1] - 1) == 0 and pool.stride(0) >= pool.shape[1] * 584
    if lse is None:
        lse = torch.empty((B, 1, H), dtype=torch.float32, device=q.device)
    assert lse.shape == (B, 1, H) and lse.dtype == torch.float32 and lse.is_contiguous()
    assert sinks is None or (sinks.shape == (H,) and sinks.dtype == torch.float32 and sinks.is_contiguous())
    cfg = _config(B, H, kv_cache.shape[1], kv_cache.stride(0), extra_kv_cache.shape[1], extra_kv_cache.stride(0),
                  float(sm_scale), float(kv_scale))
    G, nhb = cfg["G"], cfg["NHB"]
    ws = torch.empty(cfg["ws"], dtype=torch.uint8, device=q.device)
    stream = fx.Stream(torch.cuda.current_stream())
    if cfg["fused"]:
        assert state is not None and state.dtype == torch.uint8 and state.numel() >= STATE_BYTES and state.is_contiguous()
        with CompilationContext.compile_hints(dict(cfg["part_hints"])):
            launch_fused(sparse_lens.data_ptr(), extra_sparse_lens.data_ptr(), sparse_indices.data_ptr(),
                         extra_sparse_indices.data_ptr(), ws.data_ptr(), state.data_ptr(), q.data_ptr(),
                         kv_cache.data_ptr(), extra_kv_cache.data_ptr(), sinks.data_ptr() if sinks is not None else 0,
                         output.data_ptr(), lse.data_ptr(), cfg["scale2"], cfg["kv_scale"], G, nhb, cfg["HPW"],
                         cfg["SROWS"], cfg["SPB"], cfg["KROWS"], cfg["KPB"], int(sinks is not None), stream=stream)
        return (output, lse) if return_lse else output
    with CompilationContext.compile_hints(dict(cfg["part_hints"])):
        launch_part(sparse_lens.data_ptr(), extra_sparse_lens.data_ptr(), sparse_indices.data_ptr(),
                    extra_sparse_indices.data_ptr(), ws.data_ptr(), q.data_ptr(), kv_cache.data_ptr(),
                    extra_kv_cache.data_ptr(), cfg["scale2"], G, nhb, cfg["HPW"], cfg["SROWS"], cfg["SPB"],
                    cfg["KROWS"], cfg["KPB"], stream=stream)
    with CompilationContext.compile_hints({"waves_per_eu": 2}):
        launch_merge(sparse_lens.data_ptr(), extra_sparse_lens.data_ptr(), ws.data_ptr(),
                     sinks.data_ptr() if sinks is not None else 0, output.data_ptr(), lse.data_ptr(), cfg["kv_scale"],
                     G, nhb, int(sinks is not None), stream=stream)
    return (output, lse) if return_lse else output

"""DeepSeek-V4 sparse MLA decode for the C4 layers (FlyDSL, MI355X / gfx950).

Each (request, 64-head group) is a stream. A stream's keys are its window entries (sparse_indices, sparse_lens) then
its compressed entries (extra_sparse_indices, extra_sparse_lens), read from fp8 caches in the dsv4_fp8 padded-pages
layout: a page holds `rows` rows of 576 data bytes (448 e4m3 codes in 7 groups of 64, 64 bf16 rope values), then
the rows' 8 scale bytes (a power-of-two exponent a group, biased by 127).

Two launches on the caller's stream:

attn_kernel, NW workgroups of 512 threads (8 waves, one workgroup a CU: ~110 KB LDS). Every stream is cut in
  chunks of 32 keys; the chunks of all streams, concatenated, are dealt out evenly to the workgroups, so a workgroup's
  range can end one stream and start the next. A workgroup writes one partial result (normalized O, m, l) a
  (workgroup, stream) segment. Per chunk, the raw rows come in by LDS DMA one chunk ahead, and are turned into an
  fp16 tile (K = V, 32 x 512) by the bit assembly. Two wave roles, with two barriers a chunk:
  - waves 0-3 (S): wave w owns heads 16w..16w+15: S^T = K Q^T (16x16x32 fp16 MFMA, Q in registers), online softmax;
    P^T (fp16), the rescale factor and, at a segment end, (m, l) go to LDS. Then each dequantizes its share of the
    next chunk.
  - waves 4-7 (O): first each dequantizes its share of the next chunk; then wave 4 + j accumulates O^T += V^T P^T
    for heads 32 (j/2)..+31, dims 256 (j%2)..+255 (V^T read with ds_read_b64_tr_b16), and writes the segment's
    partial O (fp16) at a segment end. Workgroup 0 also writes the stream table (each stream's first chunk and
    chunk count) for the second launch.
combine_kernel, grid (streams, 8) x 256 threads: merges a stream's segment partials with the sink into out / lse.
  No workgroup of either launch waits for another; everything crosses workgroups through the launch boundary.

Precision. The tile holds 8 x the bit assembly's value as fp16: exactly for group scale bytes 117..131 (group
exponents -10..4, values up to 448 * 16). Lower groups keep values >= 2^-17, smaller ones flush to zero (a group
with a scale byte <= 116 takes a clamped path); scale bytes above 131 overflow and are not supported. Rope values
must be below 8192 in magnitude, Q below 65504 (Q is rounded to fp16). P and the partial O are fp16, the
accumulations f32. Within these bounds the result stays inside AKLR's tolerance and the physical bound of the
deployment-like draws, group magnitudes 2^-10 .. 2^10 included.
"""
import functools
import types

import torch
import flydsl.compiler as flyc
import flydsl.expr as fx
from flydsl.expr import arith, gpu, rocdl

T = fx.T
D = 512
CH = 32                  # keys a chunk
ROW = 576                # data bytes of a cache row
PITCH = 1056             # LDS bytes a tile row: 1024 + 32, conflict-free for the row and the transposed reads
NQ, NQC = 18, 14         # LDS DMA blocks a chunk (1 KB each): 14 of codes (16 a lane), 4 of rope (16 bytes a lane)
DQ_BIAS = 116            # fp16 exponent field = e4m3 exponent + scale byte - DQ_BIAS
TILE_SCALE = 8.0         # the tile holds TILE_SCALE x the value: 2^(119 - DQ_BIAS)
QK_PF = PV_PF = 4        # LDS reads in flight ahead of the MFMAs
NB = 8                   # segments a combine step
NEG = -1.0e30
LOG2E = 1.4426950408889634
LDS_MAX = 160 * 1024
NW_BY_SHAPE = types.MappingProxyType({(64, 32): 224, (64, 64): 240, (128, 16): 256, (128, 32): 256})


# ---- scalar / vector building blocks (trace-time helpers, no control flow) ----

def _v(x, ty=None):
    if isinstance(x, bool):
        return arith.constant(int(x), type=T.i32 if ty is None else ty)
    if isinstance(x, int):
        return arith.constant(x, type=T.i32 if ty is None else ty)
    if isinstance(x, float):
        return arith.constant(x, type=T.f32)
    return fx.as_ir_value(x)


def add(a, b):
    return arith.addi(_v(a), _v(b))


def sub(a, b):
    return arith.subi(_v(a), _v(b))


def mul(a, b):
    return arith.muli(_v(a), _v(b))


def udiv(a, b):
    return arith.divui(_v(a), _v(b))


def band(a, b):
    return arith.andi(_v(a), _v(b))


def bor(a, b):
    return arith.ori(_v(a), _v(b))


def shl(a, b):
    return arith.shli(_v(a), _v(b))


def shr(a, b):
    return arith.shrui(_v(a), _v(b))


def smin(a, b):
    return arith.minsi(_v(a), _v(b))


def smax(a, b):
    return arith.maxsi(_v(a), _v(b))


def _icmp(p, a, b):
    return arith.cmpi(p, _v(a), _v(b))


def lt(a, b):
    return _icmp(arith.CmpIPredicate.slt, a, b)


def le(a, b):
    return _icmp(arith.CmpIPredicate.sle, a, b)


def gt(a, b):
    return _icmp(arith.CmpIPredicate.sgt, a, b)


def ge(a, b):
    return _icmp(arith.CmpIPredicate.sge, a, b)


def eq(a, b):
    return _icmp(arith.CmpIPredicate.eq, a, b)


def ne(a, b):
    return _icmp(arith.CmpIPredicate.ne, a, b)


def land(a, b):
    return arith.andi(_v(a), _v(b))


def lor(a, b):
    return arith.ori(_v(a), _v(b))


def sel(c, a, b):
    return arith.select(_v(c), _v(a), _v(b))


def fadd(a, b):
    return arith.addf(_v(a), _v(b))


def fsub(a, b):
    return arith.subf(_v(a), _v(b))


def fmul(a, b):
    return arith.mulf(_v(a), _v(b))


def fdiv(a, b):
    return arith.divf(_v(a), _v(b))


def fmax(a, b):
    return arith.maximumf(_v(a), _v(b))


def fgt(a, b):
    return arith.cmpf(arith.CmpFPredicate.OGT, _v(a), _v(b))


def flt(a, b):
    return arith.cmpf(arith.CmpFPredicate.OLT, _v(a), _v(b))


def feq(a, b):
    return arith.cmpf(arith.CmpFPredicate.OEQ, _v(a), _v(b))


def exp2(x):
    return rocdl.exp2(T.f32, _v(x))


def log2(x):
    return rocdl.log(T.f32, _v(x))


def zext64(x):
    return arith.extui(T.i64, _v(x))


def add64(a, b):
    return arith.addi(_v(a, T.i64), _v(b, T.i64))


def as_f32(x):
    return arith.bitcast(T.f32, _v(x))


def as_i32(x):
    return arith.bitcast(T.i32, _v(x))


def vbuild(elems, dtype):
    return fx.as_ir_value(fx.Vector.from_elements([_v(e) for e in elems], dtype))


def vext(v, i):
    return fx.as_ir_value(fx.Vector(_v(v))[i])


def vcat(a, b):
    n = 2 * fx.Vector(_v(a)).numel
    return fx.as_ir_value(fx.Vector(_v(a)).shuffle(fx.Vector(_v(b)), list(range(n))))


def vpart(v, lo, n):
    return fx.as_ir_value(fx.Vector(_v(v)).shuffle(fx.Vector(_v(v)), list(range(lo, lo + n))))


def vcast(v, dtype):
    return fx.as_ir_value(fx.Vector(_v(v)).bitcast(dtype))


def splat(x, n, dtype=fx.Float32):
    return vbuild([x] * n, dtype)


def tid():
    return fx.as_ir_value(gpu.thread_idx.x)


def bid(d):
    return fx.as_ir_value(getattr(gpu.block_idx, d))


def uniform(x):
    return rocdl.readfirstlane(T.i32, _v(x))


def ballot_any(pred):
    return arith.cmpi(arith.CmpIPredicate.ne, rocdl.ballot(T.i64, _v(pred)), _v(0, T.i64))


def lane_read(v, src_lane):
    return rocdl.ds_bpermute(T.i32, shl(src_lane, 2), _v(v))


def xor_reduce(x, m, fn):
    return fn(x, fx.as_ir_value(gpu.shuffle_xor(_v(x), m, 64)))


def sched_fence():
    rocdl.sched_barrier(0)


VMEM_FENCE = 0x78F       # sched_barrier mask: ALU, MFMA, LDS and transcendental ops may cross, vector memory not


def wait(vm=None, lgkm=0):
    rocdl.s_waitcnt(vmcnt=vm, lgkmcnt=lgkm)


def barrier_lds():
    """barrier once the wave's LDS accesses are done; outstanding vector-memory ops keep flying"""
    rocdl.s_waitcnt(lgkmcnt=0)
    rocdl.s_barrier()


def mfma(a, b, c):
    return rocdl.mfma_f32_16x16x32_f16(T.vec(4, T.f32), [_v(a), _v(b), _v(c)])


# ---- memory: LDS by i32 address, global by i64 address ----

def _ptr(space, addr, align):
    return fx.inttoptr(fx.PointerType.get(T.i32, int(space), align), _v(addr))


def lds_ld(addr, ty, align):
    return fx.as_ir_value(fx.ptr_load(_ptr(fx.AddressSpace.Shared, addr, align), ty))


def lds_st(v, addr, align):
    fx.ptr_store(_v(v), _ptr(fx.AddressSpace.Shared, addr, align))


def g_ld(addr, ty, align):
    return fx.as_ir_value(fx.ptr_load(_ptr(fx.AddressSpace.Global, addr, align), ty))


def g_st(v, addr, align):
    fx.ptr_store(_v(v), _ptr(fx.AddressSpace.Global, addr, align))


def lds_dma(gaddr, laddr, size):
    """global -> LDS DMA of `size` bytes a lane to laddr + 16 lane (async: completion is waited for explicitly)"""
    rocdl.global_load_async_lds(fx.to_llvm_ptr(_ptr(fx.AddressSpace.Global, gaddr, size)),
                                fx.to_llvm_ptr(_ptr(fx.AddressSpace.Shared, laddr, 16)), size, 0)


def lds_tr16(addr):
    return rocdl.ds_read_tr16_b64_(T.vec(4, T.i16), fx.to_llvm_ptr(_ptr(fx.AddressSpace.Shared, addr, 8)))


def base_of(tensor):
    return fx.as_ir_value(fx.ptrtoint(fx.get_iter(tensor)))


def alloc_lds(nbytes):
    st = fx.SharedAllocator().allocate(fx.Array[fx.Uint8, nbytes, 16]).peek()
    return fx.as_ir_value(fx.ptrtoint(st.ptr))


# ---- layouts ----

def lds_layout(maxc):
    """attn_kernel's LDS (byte offsets)"""
    off = {}
    o = 0
    for name, n in (("stab", 16), ("wsum", 32), ("lens", 512 * 8), ("ctab", maxc * 4), ("addr", maxc * CH * 16),
                    ("vb", maxc * CH * 4), ("pb", 4 * 64 * 16), ("ab", 4 * 64 * 4), ("mlb", 4 * 64 * 8),
                    ("tile0", CH * PITCH), ("tile1", CH * PITCH), ("raw", NQ * 1024), ("rsc", NQC * 256)):
        o = (o + 15) // 16 * 16
        off[name] = o
        o += n
    off["size"] = o
    return types.SimpleNamespace(**off)


def scratch_layout(U, NW):
    """the call's scratch (bytes): stream table, then (m, l) and partial O of every segment (WG + stream ids)"""
    nseg = NW + U
    tb = (8 * (U + 1) + 4095) // 4096 * 4096
    ml = (nseg * 64 * 8 + 4095) // 4096 * 4096
    return tb, tb + ml, tb + ml + nseg * 64 * D * 2


def stream_req(u, HG):
    return udiv(u, HG) if HG > 1 else u


# ---- attn_kernel pieces ----

def dq_codes(x, bias2, clamp):
    """4 e4m3 codes (a dword) -> 2 dwords of fp16 pairs: per half, the code byte b at bits 8..15 (perm), u = y >> 1
    puts its exponent and mantissa at fp16's place (sign at bit 14); the scale enters by an add to the exponent
    field. clamp: the field may go below 1 (scale byte <= DQ_BIAS): add per 16-bit half and flush negatives to 0."""
    outs = []
    for sel_ in (0x010C000C, 0x030C020C):
        y = rocdl.perm_b32(_v(0), _v(x), _v(sel_))
        u = shr(y, 1)
        if not clamp:
            outs.append(add(add(u, band(u, 0x40004000)), bias2))   # u + (u & 0x4000): the sign to bit 15
        else:
            mag = vcast(vbuild([band(u, 0x3F803F80)], fx.Int32), fx.Int16)
            b2 = vcast(vbuild([bias2], fx.Int32), fx.Int16)
            m2 = arith.maxsi(arith.addi(mag, b2), vcast(vbuild([0], fx.Int32), fx.Int16))
            outs.append(bor(band(y, 0x80008000), vext(vcast(m2, fx.Int32), 0)))
    return outs


def rope_to_tile(x4):
    """vector<4xi32> of 8 bf16 -> 8 fp16 holding TILE_SCALE x the values (+3 on the f32 exponent)"""
    outs = []
    for e_ in range(4):
        x = vext(x4, e_)
        lo = as_f32(add(shl(x, 16), 3 << 23))
        hi = as_f32(add(band(x, 0xFFFF0000), 3 << 23))
        outs.append(vext(vcast(arith.truncf(T.vec(2, T.f16), vbuild([lo, hi], fx.Float32)), fx.Int32), 0))
    return vbuild(outs, fx.Int32)


def q_to_f16(qv):
    out = []
    for x in qv:
        f = arith.truncf(T.vec(8, T.f16), arith.extf(T.vec(8, T.f32), vcast(x, fx.BFloat16)))
        out.append(vcast(f, fx.Int32))
    return out


def piece_of(q, code, lane):
    """DMA block q (1 KB, 64 lanes): (key, piece in the row) of this lane's 16 bytes"""
    if code:
        p = add(mul(q, 64), lane)
        key = udiv(p, 28)
        return key, sub(p, mul(key, 28))
    p = add(mul(sub(q, NQC), 64), lane)
    return shr(p, 3), band(p, 7)


def dma_items(w, srole):
    """this wave's DMA blocks: (block, code?, condition). S waves (w = 0..3): w (codes), 14 + w (rope);
    O waves (w = 4..7): w, w + 4, and w + 8 for w < 6 (codes)"""
    if srole:
        return [(w, True, True), (add(w, NQC), False, True)]
    return [(w, True, True), (add(w, 4), True, True), (smin(add(w, 8), NQC - 1), True, lt(w, 6))]


def dma_ops(L, lds, i, items, lane):
    """the wave's DMAs of chunk i: (condition, [(global address, LDS address, bytes)])"""
    got = []
    for q, code, cond in items:
        key, cp = piece_of(q, code, lane)
        av = lds_ld(add(lds, add(L.addr, shl(add(shl(i, 5), key), 4))), T.vec(2, T.i64), 16)
        got.append((q, code, cond, cp, av))
    ops = []
    for q, code, cond, cp, av in got:
        if code:
            ops.append((cond, [(add64(vext(av, 0), zext64(shl(cp, 4))), add(lds, add(L.raw, mul(q, 1024))), 16),
                               (add64(vext(av, 1), zext64(shl(shr(cp, 4), 2))), add(lds, add(L.rsc, mul(q, 256))),
                                4)]))
        else:
            ops.append((cond, [(add64(vext(av, 0), zext64(add(448, shl(cp, 4)))),
                                add(lds, add(L.raw, mul(q, 1024))), 16)]))
    return ops


def dq_loads(L, lds, i, items, lane):
    """the wave's raw reads of chunk i, all issued before any use: the biases and scale bytes first (the clamp
    decision needs only them), then the data"""
    small = []
    for q, code, cond in items:
        key, cp = piece_of(q, code, lane)
        vb = lds_ld(add(lds, add(L.vb, shl(add(shl(i, 5), key), 2))), T.f32, 4)
        scw = lds_ld(add(lds, add(L.rsc, add(mul(q, 256), shl(lane, 2)))), T.i32, 4) if code else None
        small.append((q, code, cond, key, cp, vb, scw))
    got = []
    for q, code, cond, key, cp, vb, scw in small:
        x = lds_ld(add(lds, add(L.raw, add(mul(q, 1024), shl(lane, 4)))), T.vec(4, T.i32), 16)
        ok = feq(vb, 0.0)
        # (scale bytes below 100 flush the whole group either way; the floor keeps the bias inside 16 bits)
        scv = sel(ok, smax(band(shr(scw, shl(band(shr(cp, 2), 3), 3)), 255), 100), 127) if code else None
        got.append((key, cp, code, cond, ok, x, scv))
    return got


def dq_tile(got, tile, clamp, code_pieces):
    """the tile stores of the wave's code pieces (code_pieces) or rope pieces: (condition, [(LDS address, value)])"""
    out = []
    for key, cp, code, cond, ok, x, scv in got:
        if code != code_pieces:
            continue
        if code:
            bias = shl(sub(scv, DQ_BIAS), 10)
            bias2 = bor(band(bias, 0xFFFF), shl(bias, 16))
            o8 = []
            for e_ in range(4):
                o8 += dq_codes(vext(x, e_), bias2, clamp)
            ta = add(tile, add(mul(key, PITCH), shl(cp, 5)))
            out.append((cond, [(ta, vbuild(o8[0:4], fx.Int32)), (add(ta, 16), vbuild(o8[4:8], fx.Int32))]))
        else:
            xv = rope_to_tile(arith.select(ok, x, splat(0, 4, fx.Int32)))
            out.append((cond, [(add(tile, add(mul(key, PITCH), add(896, shl(cp, 4)))), xv)]))
    return out


def needs_clamp(got):
    low = None
    for key, cp, code, cond, ok, x, scv in got:
        if code:
            c = le(scv, DQ_BIAS)
            low = c if low is None else lor(low, c)
    return ballot_any(low)


def chunk_info(L, lds, i, n):
    ent = lds_ld(add(lds, add(L.ctab, shl(i, 2))), T.i32, 4)
    entn = lds_ld(add(lds, add(L.ctab, shl(smin(add(i, 1), sub(n, 1)), 2))), T.i32, 4)
    u = shr(ent, 16)
    return u, shr(entn, 16), lor(eq(add(i, 1), n), ne(shr(entn, 16), u))


def load_q(qbase, u, w, l16, lg, H, HG):
    """wave w's Q (heads 16w + l%16 of stream u, dims 8 (l/16) + 32 ks ..), 16 x 8 bf16"""
    b = stream_req(u, HG)
    hb = mul(band(u, HG - 1), 64) if HG > 1 else 0
    off = add(shl(add(mul(b, H), add(hb, add(shl(w, 4), l16))), 10), shl(lg, 4))
    return [g_ld(add64(qbase, zext64(add(off, 64 * ks))), T.vec(4, T.i32), 16) for ks in range(16)]


def qk(tile, qk_base, qf):
    """S^T of a chunk: 2 key tiles x the wave's 16 heads, f32"""
    s = [splat(0.0, 4), splat(0.0, 4)]
    aq = {}

    def ld(ks):
        for kt in range(2):
            aq[(ks, kt)] = lds_ld(add(tile, add(qk_base, kt * 16 * PITCH + 64 * ks)), T.vec(8, T.f16), 16)
    for ks in range(QK_PF):
        ld(ks)
    sched_fence()
    for ks in range(16):
        if ks + QK_PF < 16:
            ld(ks + QK_PF)
        bq = vcast(qf[ks], fx.Float16)
        for kt in range(2):
            s[kt] = mfma(aq[(ks, kt)], bq, s[kt])
        sched_fence()
    return s


def softmax(s, vbv, scale2, m_run, l_run, seg_start):
    """online softmax step over the chunk's 32 keys: (m, l, fp16 P^T, alpha)"""
    sc = []
    for kt in range(2):
        for j in range(4):
            sc.append(fadd(fmul(vext(s[kt], j), scale2), vext(vbv[kt], j)))
    mt = sc[0]
    for j in range(1, 8):
        mt = fmax(mt, sc[j])
    mt = xor_reduce(xor_reduce(mt, 16, fmax), 32, fmax)
    m_old = arith.select(seg_start, _v(NEG), m_run)
    l_old = arith.select(seg_start, _v(0.0), l_run)
    m_new = fmax(m_old, mt)
    alpha = arith.select(seg_start, _v(0.0), exp2(fsub(m_old, m_new)))
    p = [exp2(fsub(x, m_new)) for x in sc]
    ls = p[0]
    for j in range(1, 8):
        ls = fadd(ls, p[j])
    l_new = fadd(fmul(l_old, alpha), ls)
    return m_new, l_new, arith.truncf(T.vec(8, T.f16), vbuild(p, fx.Float32)), alpha


def pv(tile, tr_base, acc, pfs):
    """O^T += V^T P^T over the chunk: 16 dim tiles x 2 head tiles"""
    a2 = list(acc)
    vq = {}

    def ldv(mt_):
        parts = [lds_tr16(add(tile, add(tr_base, h * 16 * PITCH + 32 * mt_))) for h in range(2)]
        vq[mt_] = vcast(vcat(parts[0], parts[1]), fx.Float16)
    for mt_ in range(PV_PF):
        ldv(mt_)
    sched_fence()
    for mt_ in range(16):
        if mt_ + PV_PF < 16:
            ldv(mt_ + PV_PF)
        for ht in range(2):
            a2[2 * mt_ + ht] = mfma(vq[mt_], pfs[ht], a2[2 * mt_ + ht])
        sched_fence()
    return a2


def rescale(acc, alphas):
    avs = [splat(a, 4) for a in alphas]
    return [arith.mulf(a_, avs[i % 2]) for i, a_ in enumerate(acc)]


def partial_stores(acc, ht, inv, obase):
    """head tile ht's normalized O^T as fp16, 16 bytes a store: [(byte offset, value)]"""
    iv = splat(inv, 4)
    out = []
    for mp in range(8):
        h8 = [arith.truncf(T.vec(4, T.f16), arith.mulf(acc[2 * (2 * mp + e_) + ht], iv)) for e_ in range(2)]
        out.append((add(obase, mp * 1024), vcat(h8[0], h8[1])))
    return out


@flyc.kernel
def attn_kernel(Q: fx.Tensor, SWA: fx.Tensor, SWA_IDX: fx.Tensor, SWA_LEN: fx.Tensor, KV: fx.Tensor,
                KV_IDX: fx.Tensor, KV_LEN: fx.Tensor, SCR: fx.Tensor,
                H: fx.Constexpr[int], B: fx.Constexpr[int], NW: fx.Constexpr[int], MAXC: fx.Constexpr[int],
                SWA_W: fx.Constexpr[int], KV_W: fx.Constexpr[int], SWA_ROWS: fx.Constexpr[int],
                SWA_PB: fx.Constexpr[int], KV_ROWS: fx.Constexpr[int], KV_PB: fx.Constexpr[int],
                SCALE2: fx.Constexpr[float]):
    HG = H // 64
    U = B * HG
    L = lds_layout(MAXC)
    TB_OFF = 0
    ML_OFF, OP_OFF, _ = scratch_layout(U, NW)
    lds = alloc_lds(L.size)
    t = tid()
    lane = band(t, 63)
    w = uniform(shr(t, 6))
    wg = bid("x")
    scr = base_of(SCR)

    # ---- plan: every stream's chunk count, their exclusive prefix (one thread a stream) ----
    tu = smin(t, U - 1)
    bt = stream_req(tu, HG)
    sl_t = smin(smax(g_ld(add64(base_of(SWA_LEN), zext64(shl(bt, 2))), T.i32, 4), 0), SWA_W)
    kl_t = smin(smax(g_ld(add64(base_of(KV_LEN), zext64(shl(bt, 2))), T.i32, 4), 0), KV_W)
    n_t = sel(lt(t, U), shr(add(add(sl_t, kl_t), CH - 1), 5), 0)
    if lt(t, U):
        lds_st(vbuild([sl_t, kl_t], fx.Int32), add(lds, add(L.lens, shl(t, 3))), 8)
    v = n_t
    for sh in fx.range_constexpr(6):
        up = lane_read(v, smax(sub(lane, 1 << sh), 0))
        v = add(v, sel(ge(lane, 1 << sh), up, 0))
    if eq(lane, 63):
        lds_st(v, add(lds, add(L.wsum, shl(w, 2))), 4)
    barrier_lds()
    ws = [lds_ld(add(lds, L.wsum + 4 * kw), T.i32, 4) for kw in range(8)]
    pre = _v(0)
    tot = ws[0]
    for kw in fx.range_constexpr(7):
        pre = add(pre, sel(gt(w, kw), ws[kw], 0))
        tot = add(tot, ws[kw + 1])
    s_t = sub(add(pre, v), n_t)
    if land(eq(wg, 0), le(t, U)):
        g_st(vbuild([sel(lt(t, U), s_t, tot), n_t], fx.Int32), add64(scr, zext64(add(TB_OFF, shl(t, 3)))), 8)
    g0 = udiv(mul(wg, tot), NW)
    n = sub(udiv(mul(add(wg, 1), tot), NW), g0)
    a_t = smax(g0, s_t)
    e_t = smin(add(g0, n), add(s_t, n_t))
    if land(lt(a_t, e_t), eq(a_t, g0)):
        lds_st(t, add(lds, L.stab), 4)
    for g in range(a_t, e_t):
        lds_st(bor(shl(t, 16), sub(g, s_t)), add(lds, add(L.ctab, shl(sub(g, g0), 2))), 4)
    barrier_lds()

    if gt(n, 0):
        l16 = band(lane, 15)
        lg = shr(lane, 4)
        swa_b, kv_b = base_of(SWA), base_of(KV)
        sidx_b, kidx_b = base_of(SWA_IDX), base_of(KV_IDX)
        def setup_keys():
            """the workgroup's keys: (row address, scale address), softmax bias (0, or -inf if skipped)"""
            nk = shl(n, 5)
            keys = []
            for j_ in fx.range_constexpr(-(-(MAXC * CH) // 512)):
                e = add(t, 512 * j_)
                ec = smin(e, sub(nk, 1))
                ent = lds_ld(add(lds, add(L.ctab, shl(shr(ec, 5), 2))), T.i32, 4)
                u = shr(ent, 16)
                b = stream_req(u, HG)
                lv = lds_ld(add(lds, add(L.lens, shl(u, 3))), T.vec(2, T.i32), 8)
                sl, kl = vext(lv, 0), vext(lv, 1)
                pos = add(shl(band(ent, 0xFFFF), 5), band(ec, 31))
                ps = smin(pos, SWA_W - 1)
                pk = smax(smin(sub(pos, sl), KV_W - 1), 0)
                vs = g_ld(add64(sidx_b, zext64(shl(add(mul(b, SWA_W), ps), 2))), T.i32, 4)
                vk = g_ld(add64(kidx_b, zext64(shl(add(mul(b, KV_W), pk), 2))), T.i32, 4)
                keys.append((e, pos, sl, kl, vs, vk))
            for e, pos, sl, kl, vs, vk in keys:
                is_swa = lt(pos, sl)
                slot = sel(is_swa, vs, vk)
                okk = land(lor(is_swa, land(ge(pos, sl), lt(pos, add(sl, kl)))), ge(slot, 0))
                slot = sel(okk, slot, 0)
                rows = sel(is_swa, SWA_ROWS, KV_ROWS)
                page = sel(is_swa, udiv(slot, SWA_ROWS), udiv(slot, KV_ROWS))
                row = sub(slot, mul(page, rows))
                pgb = arith.muli(zext64(page), arith.select(is_swa, _v(SWA_PB, T.i64), _v(KV_PB, T.i64)))
                pg = add64(arith.select(is_swa, swa_b, kv_b), pgb)
                da = add64(pg, zext64(mul(row, ROW)))
                sa = add64(pg, zext64(add(mul(rows, ROW), shl(row, 3))))
                if lt(e, nk):
                    lds_st(vbuild([da, sa], fx.Int64), add(lds, add(L.addr, shl(e, 4))), 16)
                    lds_st(sel(okk, 0.0, float("-inf")), add(lds, add(L.vb, shl(e, 2))), 4)

        setup_keys()
        barrier_lds()

        def tile_of(i):
            return sel(eq(band(i, 1), 0), add(lds, L.tile0), add(lds, L.tile1))

        def issue_dma(i, srole):
            for cond, ops in dma_ops(L, lds, i, dma_items(w, srole), lane):
                if cond:
                    for ga, la, size in ops:
                        lds_dma(ga, la, size)
            # the compiler does not track the async DMAs; the explicit vmcnt waits count the vector-memory ops
            # issued after them, so none may be scheduled above them
            rocdl.sched_barrier(VMEM_FENCE)

        def put(stores):
            for cond, sts in stores:
                if cond:
                    for a_, v_ in sts:
                        lds_st(v_, a_, 16)

        def dequant(i, srole):
            tile = tile_of(i)
            got = dq_loads(L, lds, i, dma_items(w, srole), lane)
            if needs_clamp(got):
                put(dq_tile(got, tile, True, True))
            else:
                put(dq_tile(got, tile, False, True))
            put(dq_tile(got, tile, False, False))

        def s_waves():
            """QK + softmax of chunk k, then the dequant share of chunk k + 1"""
            qbase = base_of(Q)
            u0 = lds_ld(add(lds, L.stab), T.i32, 4)
            issue_dma(_v(0), True)
            qv = load_q(qbase, u0, w, l16, lg, H, HG)
            wait(vm=16)                                  # chunk 0's DMA; the 16 Q loads may still fly
            dequant(_v(0), True)
            barrier_lds()
            if lt(1, n):
                issue_dma(_v(1), True)
            qk_base = add(mul(l16, PITCH), shl(lg, 4))
            slot = add(shl(w, 6), lane)
            m_run = _v(NEG)
            l_run = _v(0.0)
            u_prev = _v(-1)
            for k in range(n):
                cu, cu_next, seg_end = chunk_info(L, lds, k, n)
                seg_start = ne(cu, u_prev)
                qf = qv
                if seg_start:
                    qf = q_to_f16(qv)
                s = qk(tile_of(k), qk_base, qf)
                newq = land(seg_end, lt(add(k, 1), n))
                qn = qf
                if newq:
                    qn = load_q(qbase, cu_next, w, l16, lg, H, HG)
                vbv = [lds_ld(add(lds, add(L.vb, shl(add(shl(k, 5), add(16 * kt, shl(lg, 2))), 2))),
                              T.vec(4, T.f32), 16) for kt in range(2)]
                m_new, l_new, pf, alpha = softmax(s, vbv, SCALE2, m_run, l_run, seg_start)
                lds_st(pf, add(lds, add(L.pb, shl(slot, 4))), 16)
                lds_st(alpha, add(lds, add(L.ab, shl(slot, 2))), 4)
                if seg_end:
                    l_tot = xor_reduce(xor_reduce(l_new, 16, fadd), 32, fadd)
                    lds_st(vbuild([m_new, l_tot], fx.Float32), add(lds, add(L.mlb, shl(slot, 3))), 8)
                barrier_lds()
                if lt(add(k, 1), n):
                    if newq:
                        wait(vm=16)                      # chunk k + 1's DMA; the next segment's Q may still fly
                    else:
                        wait(vm=0)
                    dequant(add(k, 1), True)
                    if lt(add(k, 2), n):
                        wait(lgkm=0)                     # the raw reads are done before the DMA overwrites them
                        issue_dma(add(k, 2), True)
                barrier_lds()
                m_run = m_new
                l_run = l_new
                u_prev = cu
                qv = qn

        def o_waves():
            """dequant share of chunk k + 1, then PV of chunk k (and the segment's partial at its end)"""
            o = sub(w, 4)
            tr_base = add(add(mul(add(shl(lg, 2), shr(l16, 2)), PITCH), shl(band(l16, 3), 3)), shl(band(o, 1), 9))
            hw0 = shl(shr(o, 1), 1)
            dh = band(o, 1)
            slots = [add(shl(add(hw0, ht), 6), lane) for ht in range(2)]
            issue_dma(_v(0), False)
            wait(vm=0)
            dequant(_v(0), False)
            barrier_lds()
            if lt(1, n):
                issue_dma(_v(1), False)
            acc = [splat(0.0, 4)] * 32
            stored = _v(0)
            for k in range(n):
                if lt(add(k, 1), n):
                    if ne(stored, 0):
                        wait(vm=16)                      # chunk k + 1's DMA; the partial's stores may drain
                    else:
                        wait(vm=0)
                    dequant(add(k, 1), False)
                    if lt(add(k, 2), n):
                        wait(lgkm=0)
                        issue_dma(add(k, 2), False)
                barrier_lds()
                alphas = [lds_ld(add(lds, add(L.ab, shl(sl, 2))), T.f32, 4) for sl in slots]
                pfs = [lds_ld(add(lds, add(L.pb, shl(sl, 4))), T.vec(8, T.f16), 16) for sl in slots]
                a2 = acc
                if ballot_any(lor(flt(alphas[0], 1.0), flt(alphas[1], 1.0))):
                    a2 = rescale(acc, alphas)
                a2 = pv(tile_of(k), tr_base, a2, pfs)
                cu, cu_next, seg_end = chunk_info(L, lds, k, n)
                if seg_end:
                    sid = add(wg, cu)
                    for ht in fx.range_constexpr(2):
                        ml = lds_ld(add(lds, add(L.mlb, shl(slots[ht], 3))), T.vec(2, T.f32), 8)
                        l_tot = vext(ml, 1)
                        inv = arith.select(fgt(l_tot, 0.0), fdiv(1.0, l_tot), _v(0.0))
                        hw = add(hw0, ht)
                        # [segment][head tile][dim-tile pair][lane][2][4] fp16
                        obase = add(OP_OFF, add(add(shl(add(shl(sid, 2), hw), 14), shl(lane, 4)), shl(dh, 13)))
                        for off_, val in partial_stores(a2, ht, inv, obase):
                            g_st(val, add64(scr, zext64(off_)), 16)
                        if land(lt(lane, 16), eq(dh, 0)):
                            g_st(ml, add64(scr, zext64(add(ML_OFF, shl(add(shl(sid, 6), add(shl(hw, 4), lane)), 3)))),
                                 8)
                barrier_lds()
                acc = a2
                stored = arith.extui(T.i32, seg_end)

        if lt(w, 4):
            s_waves()
        else:
            o_waves()


# ---- combine_kernel ----

def merge_step(scr, ML_OFF, OP_OFF, u, hl, hw, mt0, lane, w0, w_hi, tot, NW, M, Lc, acc):
    """merge segments w0 .. w0 + NB - 1 (those <= w_hi) of stream u into (M, Lc, acc); all loads first"""
    segs = []
    for jj in range(NB):
        ww = add(w0, jj)
        wc = smin(ww, w_hi)
        sid = add(wc, u)
        mlv = g_ld(add64(scr, zext64(add(ML_OFF, shl(add(shl(sid, 6), hl), 3)))), T.vec(2, T.f32), 8)
        obase = add(OP_OFF, add(shl(add(shl(add(shl(sid, 2), hw), 5), mt0), 9), shl(lane, 4)))
        os_ = []
        for p_ in range(2):
            v8 = g_ld(add64(scr, zext64(add(obase, 1024 * p_))), T.vec(8, T.f16), 16)
            os_ += [vpart(v8, 0, 4), vpart(v8, 4, 4)]
        nonempty = lt(udiv(mul(wc, tot), NW), udiv(mul(add(wc, 1), tot), NW))
        segs.append((le(ww, w_hi), nonempty, mlv, os_))
    sched_fence()
    z4 = splat(0.0, 4)
    for inr, nonempty, mlv, os_ in segs:
        ms, lsg = vext(mlv, 0), vext(mlv, 1)
        okk = land(land(fgt(lsg, 0.0), nonempty), inr)
        M2 = arith.select(okk, fmax(M, ms), M)
        ca = exp2(fsub(M, M2))
        cb = arith.select(okk, fmul(lsg, exp2(fsub(ms, M2))), _v(0.0))
        av, bv = splat(ca, 4), splat(cb, 4)
        acc = [arith.addf(arith.mulf(acc[j], av),
                          arith.mulf(arith.select(okk, arith.extf(T.vec(4, T.f32), os_[j]), z4), bv))
               for j in range(4)]
        Lc = fadd(fmul(Lc, ca), cb)
        M = M2
    return M, Lc, acc


@flyc.kernel
def combine_kernel(SCR: fx.Tensor, SINK: fx.Tensor, OUT: fx.Tensor, LSE: fx.Tensor,
                   H: fx.Constexpr[int], B: fx.Constexpr[int], NW: fx.Constexpr[int], KVS: fx.Constexpr[float],
                   HAS_SINK: fx.Constexpr[int]):
    """WG (stream u, eighth hq), wave w, lane l: head 16 (hq/2) + l%16, dims 16 (16 (hq%2) + 4w + j) + 4 (l/16) .."""
    HG = H // 64
    U = B * HG
    ML_OFF, OP_OFF, _ = scratch_layout(U, NW)
    t = tid()
    lane = band(t, 63)
    w = shr(t, 6)
    u = bid("x")
    hq = bid("y")
    scr = base_of(SCR)
    sn = g_ld(add64(scr, zext64(shl(u, 3))), T.vec(2, T.i32), 8)
    tot = g_ld(add64(scr, U * 8), T.i32, 4)
    s_u, n_u = vext(sn, 0), vext(sn, 1)
    b = stream_req(u, HG)
    hw = shr(hq, 1)
    hl = add(shl(hw, 4), band(lane, 15))
    mt0 = add(shl(band(hq, 1), 4), shl(w, 2))
    h = add(mul(band(u, HG - 1), 64), hl) if HG > 1 else hl
    tm = smax(tot, 1)
    # the workgroups holding the stream's first and last chunk
    w_lo = smin(sub(udiv(add(mul(add(s_u, 1), NW), sub(tm, 1)), tm), 1), NW - 1)
    w_hi = sel(gt(n_u, 0), smin(sub(udiv(add(mul(add(s_u, n_u), NW), sub(tm, 1)), tm), 1), NW - 1), sub(w_lo, 1))
    sink = g_ld(add64(base_of(SINK), zext64(shl(h, 2))), T.f32, 4) if HAS_SINK else None
    M = _v(NEG)
    Lc = _v(0.0)
    acc = [splat(0.0, 4)] * 4
    for w0 in range(w_lo, add(w_hi, 1), NB):
        M, Lc, acc = merge_step(scr, ML_OFF, OP_OFF, u, hl, hw, mt0, lane, w0, w_hi, tot, NW, M, Lc, acc)
    den = fadd(Lc, exp2(fsub(fmul(sink, LOG2E), M))) if HAS_SINK else Lc
    has = fgt(Lc, 0.0)
    iv = splat(arith.select(has, fdiv(KVS, den), _v(0.0)), 4)
    orow = add(mul(add(mul(b, H), h), D * 2), shl(shr(lane, 4), 3))
    ob = base_of(OUT)
    for j in fx.range_constexpr(4):
        o16 = arith.truncf(T.vec(4, T.bf16), arith.mulf(acc[j], iv))
        g_st(o16, add64(ob, zext64(add(orow, shl(add(mt0, j), 5)))), 8)
    lse = arith.select(has, fmul(fadd(M, log2(Lc)), 1.0 / LOG2E), _v(float("inf")))
    if land(eq(band(hq, 1), 0), land(eq(w, 0), lt(lane, 16))):
        g_st(lse, add64(base_of(LSE), zext64(shl(add(mul(b, H), h), 2))), 4)


@flyc.jit
def launch(Q: fx.Tensor, SWA: fx.Tensor, SWA_IDX: fx.Tensor, SWA_LEN: fx.Tensor, KV: fx.Tensor, KV_IDX: fx.Tensor,
           KV_LEN: fx.Tensor, SINK: fx.Tensor, OUT: fx.Tensor, LSE: fx.Tensor, SCR: fx.Tensor,
           H: fx.Constexpr[int], B: fx.Constexpr[int], NW: fx.Constexpr[int], MAXC: fx.Constexpr[int],
           SWA_W: fx.Constexpr[int], KV_W: fx.Constexpr[int], SWA_ROWS: fx.Constexpr[int], SWA_PB: fx.Constexpr[int],
           KV_ROWS: fx.Constexpr[int], KV_PB: fx.Constexpr[int], SCALE2: fx.Constexpr[float],
           KVS: fx.Constexpr[float], HAS_SINK: fx.Constexpr[int], stream: fx.Stream = fx.Stream(None)):
    attn_kernel(Q, SWA, SWA_IDX, SWA_LEN, KV, KV_IDX, KV_LEN, SCR, H, B, NW, MAXC, SWA_W, KV_W, SWA_ROWS, SWA_PB,
                KV_ROWS, KV_PB, SCALE2).launch(grid=(NW, 1, 1), block=(512, 1, 1), stream=stream)
    combine_kernel(SCR, SINK, OUT, LSE, H, B, NW, KVS, HAS_SINK,
                   value_attrs={"rocdl.waves_per_eu": 1}).launch(grid=(B * H // 64, 8, 1), block=(256, 1, 1),
                                                                  stream=stream)


# ---- host side ----

@functools.cache
def plan(B, H, swa_w, kv_w, swa_rows, swa_pb, kv_rows, kv_pb, sm_scale, kv_scale, has_sink):
    """the configuration of a shape: (scratch bytes, launch with its compile-time arguments bound)"""
    if H % 64 or not 0 < B * H // 64 < 512:
        raise ValueError(f"unsupported heads / batch: {H}, {B}")
    U = B * H // 64
    nw = NW_BY_SHAPE.get((H, B), 96 if U <= 16 else (192 if U <= 32 else 256))
    maxc = -(-(U * -(-(swa_w + kv_w) // CH)) // nw) + 1
    if lds_layout(maxc).size > LDS_MAX:
        raise ValueError(f"too many chunks a workgroup: {maxc}")
    consts = (H, B, nw, maxc, swa_w, kv_w, swa_rows, swa_pb, kv_rows, kv_pb,
              float(sm_scale * kv_scale * LOG2E / TILE_SCALE), float(kv_scale / TILE_SCALE), int(has_sink))
    return scratch_layout(U, nw)[2], consts


def _pool_base(pool):
    """the pool as a one-byte view at its base: the kernel addresses pages itself, and the pool's size stays out of
    the compiled signature"""
    return torch.as_strided(pool.view(torch.uint8), (1,), (1,))


def run(*, q, kv_cache, sparse_indices, sparse_lens, extra_kv_cache, extra_sparse_indices, extra_sparse_lens,
        block_table=None, cache_seqlens=None, cu_seqlens_k=None, causal=False, head_dim_v=D, sm_scale=None,
        sinks=None, kv_cache_format="dsv4_fp8", kv_scale=1.0, return_lse=True, kv_cache_layout="padded_pages",
        output=None, lse=None):
    if kv_cache_format != "dsv4_fp8" or kv_cache_layout != "padded_pages" or causal or head_dim_v != D:
        raise ValueError("supported: dsv4_fp8 padded pages, non-causal, head_dim_v 512")
    if block_table is not None or cache_seqlens is not None or cu_seqlens_k is not None:
        raise ValueError("block_table / cache_seqlens / cu_seqlens_k are not used by this kernel")
    B, _, H, d = q.shape
    if d != D or q.dtype != torch.bfloat16 or not q.is_contiguous():
        raise ValueError("q: contiguous bf16 [batch][1][heads][512]")
    for x in (sparse_indices, sparse_lens, extra_sparse_indices, extra_sparse_lens):
        if x.dtype != torch.int32 or not x.is_contiguous():
            raise ValueError("indices and lengths: contiguous int32")
    if sm_scale is None:
        sm_scale = D ** -0.5
    if output is None:
        output = torch.empty(B, 1, H, D, dtype=torch.bfloat16, device=q.device)
    if not output.is_contiguous() or (lse is not None and not lse.is_contiguous()):
        raise ValueError("output / lse: contiguous")
    lse_out = lse if lse is not None else torch.empty(B, 1, H, dtype=torch.float32, device=q.device)
    swa_w, kv_w = sparse_indices.shape[-1], extra_sparse_indices.shape[-1]
    nbytes, consts = plan(B, H, swa_w, kv_w, kv_cache.shape[1], kv_cache.stride(0), extra_kv_cache.shape[1],
                          extra_kv_cache.stride(0), float(sm_scale), float(kv_scale), sinks is not None)
    scratch = torch.empty(nbytes, dtype=torch.uint8, device=q.device)
    launch(q, _pool_base(kv_cache), sparse_indices, sparse_lens, _pool_base(extra_kv_cache), extra_sparse_indices,
           extra_sparse_lens, sinks if sinks is not None else scratch, output, lse_out, scratch, *consts,
           stream=fx.Stream(torch.cuda.current_stream()))
    return (output, lse_out) if return_lse else output
